-- 11. OPUS — SAT_LNK_CLAIM_PARTY_ROLE   [Implemented]
-- Multi-active: a version is the whole member set loaded at one LOAD_DATETIME; two
-- consecutive identical sets = an unchanged group was re-inserted. standard satellite,
-- automate_dv.ma_sat; PK CLAIM_PARTY_HKEY, child key PARTY_ROLE_TYPE, ROLE_SEQUENCE; 1
-- RECORD_SOURCE group(s): OPUS_CLM_INTERESTED_PARTIES [2 col(s)]. Multi-active: compared
-- per (key, child key); latest = max LOAD_DATETIME per member.
----------------------------------------------------------------------------------------
with grp as (  -- one signature per loaded group (key, RECORD_SOURCE, LOAD_DATETIME)
    select CLAIM_PARTY_HKEY, RECORD_SOURCE, LOAD_DATETIME,
           listagg(to_varchar(PARTY_ROLE_TYPE) || to_varchar(ROLE_SEQUENCE) || ':' || to_varchar(HASHDIFF, 'HEX'), ',')
               within group (order by PARTY_ROLE_TYPE, ROLE_SEQUENCE, HASHDIFF) as sig
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_LNK_CLAIM_PARTY_ROLE
     where startswith(RECORD_SOURCE, 'OPUS_')
     group by CLAIM_PARTY_HKEY, RECORD_SOURCE, LOAD_DATETIME
),
seq as (
    select *, lag(sig) over (partition by CLAIM_PARTY_HKEY, RECORD_SOURCE order by LOAD_DATETIME) as prev_sig from grp
)
select 'OPUS' as project, 'SAT_LNK_CLAIM_PARTY_ROLE' as satellite,
       count(*) as versions, count_if(sig = prev_sig) as unchanged_reinserts,
       array_slice(array_agg(iff(sig = prev_sig, to_varchar(CLAIM_PARTY_HKEY, 'HEX'), null)) within group (order by CLAIM_PARTY_HKEY), 0, 3) as examples,
       iff(unchanged_reinserts = 0, 'PASS', 'FAIL') as status
  from seq;



